/* Country lookup for travel and migrant health. Data in countries-data.js (generated by gen_countries.py).
   Malaria: UKHSA Guidelines for malaria prevention in travellers from the UK (2026). */
(function () {
  var host = document.getElementById('ctry');
  if (!host || !window.COUNTRIES) return;
  var C = window.COUNTRIES;
  var VHF = 'https://assets.publishing.service.gov.uk/media/6aa2833e92e72b8ac437f0b8/viral-haemorrhagic-fevers-risk-assessment-algorithm-september-2026.pdf';
  var F = {
    lassa: ['Lassa fever', 'red', 'Endemic. Fever within 21 days of return: VHF risk assessment.', ['VHF algorithm', VHF]],
    filo: ['Ebola or Marburg', 'red', 'Outbreaks have occurred: check for a current outbreak. Fever within 21 days of return: VHF risk assessment.', ['VHF algorithm', VHF]],
    cchf: ['Crimean-Congo haemorrhagic fever', 'red', 'Tick bite, livestock slaughter or healthcare exposure, with fever within 21 days of return: VHF risk assessment.', ['VHF algorithm', VHF]],
    mers: ['MERS coronavirus', 'red', 'Fever and respiratory illness within 14 days of return, especially with camel or healthcare contact: follow the UKHSA MERS guidance (HCID).', ['UKHSA MERS guidance', 'https://www.gov.uk/guidance/mers-cov-diagnosis-and-management-of-cases-and-contacts']],
    yf: ['Yellow fever', 'amber', 'Risk of transmission (WHO list): check vaccination status; consider in fever with jaundice.', null],
    mb: ['Meningitis belt', 'amber', 'Meningococcal disease, especially in the dry season (December to June).', null],
    xdrt: ['XDR typhoid', 'red', 'Extensively drug-resistant Salmonella Typhi: use a carbapenem (often with azithromycin) for suspected enteric fever.', null],
    polio: ['Wild poliovirus', 'amber', 'Wild poliovirus type 1 is still circulating.', null],
    mdr: ['MDR-TB burden', 'amber', 'High burden of multidrug or rifampicin-resistant TB (WHO list): send rapid molecular resistance testing.', null],
    cpe: ['Carbapenemase producers', 'amber', 'High prevalence of carbapenemase-producing Enterobacterales: screen and isolate after a hospital stay here.', null]
  };
  var MAL = { H: ['Malaria: high risk', 'red'], P: ['Malaria: risk in some areas', 'amber'], L: ['Malaria: low risk', 'green'], N: ['No malaria', 'grey'] };
  var MRANK = { H: 3, P: 2, L: 1, N: 0 };
  var st = { q: '', sel: [] };

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function fold(s) { return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z ]+/g, ' ').replace(/\s+/g, ' ').trim(); }
  var ALIAS = { 'drc': 'DR Congo', 'zaire': 'DR Congo', 'ivory coast': "Côte d'Ivoire", 'turkey': 'Türkiye', 'uae': 'United Arab Emirates', 'dubai': 'United Arab Emirates', 'abu dhabi': 'United Arab Emirates', 'usa': 'United States', 'us': 'United States', 'america': 'United States', 'burma': 'Myanmar', 'east timor': 'Timor-Leste', 'swaziland': 'Eswatini', 'png': 'Papua New Guinea', 'korea': 'South Korea', 'holland': 'Netherlands', 'czech republic': 'Czechia', 'zanzibar': 'Tanzania', 'kruger': 'South Africa', 'bali': 'Indonesia', 'goa': 'India', 'kerala': 'India', 'sabah': 'Malaysia', 'borneo': 'Malaysia' };
  function find(q) {
    var f = fold(q);
    if (!f) return [];
    var hits = C.filter(function (c) { var n = fold(c.n); return n.indexOf(f) === 0 || n.indexOf(' ' + f) >= 0; });
    Object.keys(ALIAS).forEach(function (a) { if (a.indexOf(f) === 0) C.forEach(function (c) { if (c.n === ALIAS[a] && hits.indexOf(c) < 0) hits.push(c); }); });
    if (!hits.length) hits = C.filter(function (c) { return fold(c.r).indexOf(f) >= 0; });
    return hits;
  }
  function get(n) { for (var i = 0; i < C.length; i++) if (C[i].n === n) return C[i]; return null; }
  function base() { return ((document.querySelector('script[data-base]') || { getAttribute: function () { return ''; } }).getAttribute('data-base') || '').replace(/\/$/, ''); }
  function href(u) { return document.getElementById('view-links') ? '#' + u.replace(/^\/|\/$/g, '') : base() + u; }

  function shell() {
    host.innerHTML = '<div class="ab-sec"><h4><label for="ct-q">Countries visited</label></h4></div>' +
      '<input id="ct-q" type="search" placeholder="Type a country, e.g. Nigeria, India, Brazil" autocomplete="off" spellcheck="false">' +
      '<div id="ct-list" class="opts wide si-list"></div><div id="ct-sel" class="ct-sel"></div><div id="ct-out" aria-live="polite"></div>';
    draw();
  }

  function draw() {
    var list = host.querySelector('#ct-list'), sel = host.querySelector('#ct-sel'), out = host.querySelector('#ct-out');
    var hits = find(st.q);
    list.innerHTML = st.q ? (hits.length ? hits.slice(0, 24).map(function (c) {
      return '<button type="button" class="opt' + (st.sel.indexOf(c.n) >= 0 ? ' on' : '') + '" data-c="' + esc(c.n) + '"><span class="opt-text">' + esc(c.n) + '</span><span class="opt-pts">' + esc(c.r) + '</span></button>';
    }).join('') : '<p class="ab-note">No match. Not every country is listed: use TravelHealthPro for others.</p>') : '';
    sel.innerHTML = st.sel.length ? st.sel.map(function (n) { return '<button type="button" class="ct-tag" data-rm="' + esc(n) + '" aria-label="Remove ' + esc(n) + '">' + esc(n) + ' <span aria-hidden="true">×</span></button>'; }).join('') : '';
    if (!st.sel.length) { out.innerHTML = '<p class="ab-note">Add one or more countries. Each shows the UKHSA malaria advice, haemorrhagic fever and other notable risks, and a link to the TravelHealthPro country page.</p>'; out.removeAttribute('data-text'); return; }
    var cs = st.sel.map(get), h = '', t = [];
    // Combined summary
    var worst = cs.reduce(function (m, c) { return MRANK[c.m] > MRANK[m] ? c.m : m; }, 'N');
    var flags = {};
    cs.forEach(function (c) { c.f.forEach(function (f) { (flags[f] = flags[f] || []).push(c.n); }); });
    var hcid = ['lassa', 'filo', 'cchf', 'mers'].filter(function (f) { return flags[f]; });
    if (cs.length > 1 || hcid.length) {
      h += '<div class="ct-sum"><h3>Summary for this trip</h3><ul>';
      h += '<li><span class="ct-pill t-' + MAL[worst][1] + '">' + esc(MAL[worst][0]) + '</span> ' + (worst === 'N' ? 'none of these countries has malaria.' : 'highest malaria risk across the trip: ' + esc(cs.filter(function (c) { return c.m === worst; }).map(function (c) { return c.n; }).join(', ')) + '.') + '</li>';
      if (hcid.length) h += '<li><span class="ct-pill t-red">HCID</span> ' + esc(hcid.map(function (f) { return F[f][0] + ' (' + flags[f].join(', ') + ')'; }).join('; ')) + '. <a href="' + VHF + '" target="_blank" rel="noopener">VHF algorithm <span class="ext" aria-hidden="true">↗</span></a></li>';
      h += '</ul></div>';
    }
    t.push('Travel: ' + st.sel.join(', ') + '.');
    cs.forEach(function (c) {
      h += '<section class="ct-card"><header><h3>' + esc(c.n) + '</h3><small>' + esc(c.r) + '</small></header>';
      h += '<p class="ct-mal"><span class="ct-pill t-' + MAL[c.m][1] + '">' + esc(MAL[c.m][0]) + '</span> ' + esc(c.mt) + '</p>';
      if (c.f.length) h += '<ul class="ct-flags">' + c.f.map(function (f) {
        var x = F[f];
        return '<li><span class="ct-pill t-' + x[1] + '">' + esc(x[0]) + '</span> ' + esc(x[2]) + (x[3] ? ' <a href="' + esc(x[3][1]) + '" target="_blank" rel="noopener">' + esc(x[3][0]) + ' <span class="ext" aria-hidden="true">↗</span></a>' : '') + '</li>';
      }).join('') + '</ul>';
      h += '<p class="ct-also"><b>Also consider:</b> ' + esc((c.d ? ['Dengue'] : []).concat(c.c).join(', ')) + '.</p>';
      h += '<div class="rf-linkrow ie-links"><a href="' + esc(c.u) + '" target="_blank" rel="noopener">TravelHealthPro: ' + esc(c.n) + ' <span class="ext" aria-hidden="true">↗</span></a></div></section>';
      t.push('- ' + c.n + ': ' + (c.m === 'N' ? 'no malaria' : 'malaria ' + c.mt.charAt(0).toLowerCase() + c.mt.slice(1).replace(/\.$/, '')) + (c.f.length ? '; ' + c.f.map(function (f) { return F[f][0]; }).join(', ') : '') + '.');
    });
    h += '<div class="rf-linkrow ie-links ct-site"><a href="' + esc(href('/returned-traveller/')) + '">Returned traveller with fever</a><a href="' + esc(href('/malaria/')) + '">Malaria guide</a><a href="' + esc(href('/isolation/')) + '">Isolation and precautions</a></div>';
    h += '<p class="ab-note">Any hospital stay abroad in the past 12 months: screen for carbapenemase-producing organisms and isolate until negative, whatever the country.</p>';
    h += '<div class="ie-actions"><button type="button" class="reset" data-copy>Copy for Epic</button></div>';
    t.push('', 'Country risks from Micro.Links country lookup (UKHSA malaria guidelines 2026); check TravelHealthPro for current outbreaks.');
    out.innerHTML = h;
    out.setAttribute('data-text', t.join('\n'));
  }

  function copy(btn) {
    var text = host.querySelector('#ct-out').getAttribute('data-text') || '';
    function done(ok) { var o = btn.textContent; btn.textContent = ok ? 'Copied' : 'Select and copy below'; setTimeout(function () { btn.textContent = o; }, 1800); }
    function fallback() { var ta = document.createElement('textarea'); ta.value = text; ta.className = 'mc-copy-box'; btn.parentNode.appendChild(ta); ta.select(); var ok = false; try { ok = document.execCommand('copy'); } catch (e) {} if (ok) ta.parentNode.removeChild(ta); done(ok); }
    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(function () { done(true); }, fallback); else fallback();
  }
  function addC(n) { if (st.sel.indexOf(n) < 0) st.sel.push(n); }

  host.addEventListener('input', function (e) { if (e.target.id === 'ct-q') { st.q = e.target.value; draw(); } });
  host.addEventListener('keydown', function (e) {
    if (e.target.id === 'ct-q' && e.key === 'Enter') { e.preventDefault(); var h = find(st.q); if (h.length) { addC(h[0].n); st.q = ''; e.target.value = ''; draw(); } }
  });
  host.addEventListener('click', function (e) {
    var c = e.target.closest('[data-c]');
    if (c) { var n = c.getAttribute('data-c'), i = st.sel.indexOf(n); if (i >= 0) st.sel.splice(i, 1); else addC(n); st.q = ''; host.querySelector('#ct-q').value = ''; draw(); host.querySelector('#ct-q').focus(); return; }
    var r = e.target.closest('[data-rm]');
    if (r) { st.sel.splice(st.sel.indexOf(r.getAttribute('data-rm')), 1); draw(); return; }
    var k = e.target.closest('[data-copy]');
    if (k) copy(k);
  });
  shell();
  window.COUNTRY_LOOKUP = { find: find, st: st, draw: draw };
})();
